fields.computeBody:
if(!$props.isFillScreen) return 0
const info = getDeviceInfo()
if (info.platform === 'miniprogram') {
  return info.statusBarHeight || 0
}
return 0

// 可直接使用同级数据池字段名作为变量（无需形参）
// return 的值即为该字段的计算值
const info = getDeviceInfo()
const mb = info.menuButton
if (!mb) {
  // H5：固定导航内容区高度，加上顶部预留
  return offsetTop + 44
}
// 胶囊相对状态栏的上间距，导航区上下对称：gap + capsule + gap
const gap = Math.max(0, (mb.top || 0) - (info.statusBarHeight || 0))
return offsetTop + (mb.height || 28) + gap * 2

// 可直接使用同级数据池字段名作为变量（无需形参）
// return 的值即为该字段的计算值
const info = getDeviceInfo()
if (info.menuButton?.height) return info.menuButton.height
return 28

// 可直接使用同级数据池字段名作为变量（无需形参）
// return 的值即为该字段的计算值
const info = getDeviceInfo()
const size = navButtonSize
// 父级已有 paddingTop=offsetTop，绝对定位相对「内容区」而非屏幕顶
if (info.menuButton?.top != null) {
  return Math.max(0, (info.menuButton.top || 0) - offsetTop)
}
// H5 无胶囊：在导航内容区内垂直居中
const content = Math.max(0, height - offsetTop)
return Math.max(0, (content - size) / 2)
